"""Mint a Gemmini backend package whose block schedule is GENERATED by merlin's scheduling pass.

The hand-written package variants differ only in how ``_matmul_trace`` orders its block moves -- each one
a measured scheduling policy, edited by hand into a copy of its parent. This replaces the hand edit:

  1. derive the target's :class:`Geometry` from its RTL facts and REFUSE unless it equals the geometry the
     parent package baked (``DIM``, ``SPAD_ROWS``, ``SPAD_BANK_ROWS``, ``ACC_ROWS``);
  2. copy the parent, VENDOR ``merlin/compile/scheduling/block_schedule.py`` into it byte for byte (that
     module imports nothing from merlin, so the package still has no runtime dependency on it), and write
     ``lowering/scheduled_trace.py`` from ``package_template/`` with the geometry and knobs as literals;
  3. rename the parent's ``_matmul_trace``/``_conv_loop_trace`` to ``*_parent`` and append wrappers that
     route every command the pass models to the pass, and everything it does not (a transposed contraction,
     a pooling epilogue) back to the parent's own lowering -- never approximated;
  4. record the lineage (parent, pass module digest, knobs, geometry) in ``manifest.yaml``, write
     ``SHA256SUMS`` and freeze the package read-only under a content address.

The package is minted, never edited: re-running with the same inputs returns the same package.

Usage::

    .venv/bin/python merlin/experiments/scheduled_backend_v0/scripts/mint.py \\
        --parent gemmini_xdsl_rtl_v1_convzero --label la1 \\
        --knobs '{"lookahead_steps": 1, "load_grouping": "role"}'
"""

from __future__ import annotations

import argparse
import ast
import dataclasses
import hashlib
import json
import shutil
import sys
import time
from pathlib import Path

from merlin.common.paths import artifacts_dir
from merlin.compile.scheduling import Knobs, block_schedule, geometry_from_address_space
from merlin.targetgen.address_space import derive_address_space

TEMPLATE = Path(__file__).resolve().parent.parent / "package_template" / "scheduled_trace.py"
SOURCE_ROOT = "mlir_oot"
LOWERING = f"{SOURCE_ROOT}/lowering"
SKIP = {"__pycache__", "build", ".pytest_cache"}
#: Parent constant -> the Geometry field it must equal.
CONSTANTS = {
    "DIM": "block",
    "SPAD_ROWS": "operand_rows",
    "SPAD_BANK_ROWS": "operand_bank_rows",
    "ACC_ROWS": "accumulator_rows",
}
TRACES = ("_matmul_trace", "_conv_loop_trace")


def package_constants(source: str) -> dict[str, int]:
    """Module-level ``NAME = <int expression>`` constants, evaluated structurally; others skipped."""
    env: dict[str, int] = {}
    ops = {
        ast.FloorDiv: lambda a, b: a // b,
        ast.Mult: lambda a, b: a * b,
        ast.Add: lambda a, b: a + b,
        ast.Sub: lambda a, b: a - b,
        ast.LShift: lambda a, b: a << b,
    }

    def _eval(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, int):
            return node.value
        if isinstance(node, ast.Name) and node.id in env:
            return env[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in ops:
            return ops[type(node.op)](_eval(node.left), _eval(node.right))
        raise ValueError("not a plain integer expression")

    for stmt in ast.parse(source).body:
        if isinstance(stmt, ast.Assign) and len(stmt.targets) == 1 and isinstance(stmt.targets[0], ast.Name):
            try:
                env[stmt.targets[0].id] = _eval(stmt.value)
            except (ValueError, ZeroDivisionError):
                continue
    return env


def _files(root: Path) -> list[Path]:
    return sorted(
        p
        for p in root.rglob("*")
        if p.is_file() and not SKIP.intersection(p.relative_to(root).parts) and p.name != "SHA256SUMS"
    )


def source_digest(package: Path) -> str:
    """Content address over the emitting sources: sha256 of (relative path, bytes digest) pairs."""
    h = hashlib.sha256()
    for p in _files(package / SOURCE_ROOT):
        h.update(p.relative_to(package).as_posix().encode() + b"\0" + hashlib.sha256(p.read_bytes()).digest())
    return h.hexdigest()


def _write_sums(package: Path) -> None:
    lines = [
        f"{hashlib.sha256(p.read_bytes()).hexdigest()}  ./{p.relative_to(package).as_posix()}" for p in _files(package)
    ]
    (package / "SHA256SUMS").write_text("\n".join(lines) + "\n")


def verify(package: Path) -> None:
    """Refuse a package whose files are not the bytes its ``SHA256SUMS`` records."""
    sums = package / "SHA256SUMS"
    if not sums.is_file():
        raise SystemExit(f"{package} has no SHA256SUMS")
    for line in sums.read_text().splitlines():
        digest, _, rel = line.partition("  ")
        path = package / rel.removeprefix("./")
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != digest:
            raise SystemExit(f"{package}: {rel} is not its recorded bytes")


def _set_mode(package: Path, frozen: bool) -> None:
    for p in sorted(package.rglob("*"), reverse=True):
        if p.is_symlink():
            continue
        if p.is_dir():
            p.chmod(0o555 if frozen else 0o755)
        else:
            executable = p.stat().st_mode & 0o111
            p.chmod((0o555 if executable else 0o444) if frozen else (0o755 if executable else 0o644))
    package.chmod(0o555 if frozen else 0o755)


def thaw(package: Path) -> None:
    """Make a minted package writable again (to delete or replace it)."""
    _set_mode(package, frozen=False)


def _patch_isa(source: str) -> str:
    """Rename the parent's two traces to ``*_parent`` and append generated wrappers routing to the pass."""
    tree = ast.parse(source)
    lines = source.splitlines(keepends=True)
    found = {node.name: node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name in TRACES}
    missing = sorted(set(TRACES) - set(found))
    if missing:
        raise SystemExit(f"the parent lowering defines no {missing}; it is not a package this generator knows")
    for name, node in found.items():
        line = lines[node.lineno - 1]
        if f"def {name}(" not in line:
            raise SystemExit(f"cannot locate the definition line of {name}")
        lines[node.lineno - 1] = line.replace(f"def {name}(", f"def {name}_parent(", 1)
    wrappers = """

# ------------------------------------------------------------------------------------------------------
# GENERATED by merlin/experiments/scheduled_backend_v0/scripts/mint.py. Block moves are ordered by the
# vendored scheduling pass (lowering/block_schedule.py); commands it does not model use the parent's own
# lowering above, unchanged.


def _matmul_trace(program: InterfaceProgram, lhs_name: str, weight_name: str, out_name: str,
                  attrs: dict[str, Any], *, transpose_b: bool = False) -> list[Instruction]:
    from lowering import scheduled_trace
    if transpose_b or "maxpool" in (attrs.get("epilogue") or []) or not scheduled_trace.supports(attrs):
        return _matmul_trace_parent(program, lhs_name, weight_name, out_name, attrs, transpose_b=transpose_b)
    return scheduled_trace.matmul(program, lhs_name, weight_name, out_name, attrs)


def _conv_loop_trace(program: InterfaceProgram, command: dict[str, Any], weight_name: str) -> list[Instruction]:
    from lowering import scheduled_trace
    if not scheduled_trace.supports(command.get("attributes") or {}):
        return _conv_loop_trace_parent(program, command, weight_name)
    return scheduled_trace.conv(program, command, weight_name)
"""
    return "".join(lines).rstrip("\n") + "\n" + wrappers


def mint(
    target: str,
    parent_id: str,
    knobs: Knobs,
    conv_knobs: Knobs,
    label: str,
    dest_root: Path | None = None,
    parents_root: Path | None = None,
    freeze: bool = True,
    coalesce_gather: bool = False,
) -> Path:
    import yaml

    knobs.validate()
    conv_knobs.validate()
    parents_root = Path(parents_root) if parents_root else artifacts_dir() / "targets" / target
    dest_root = Path(dest_root) if dest_root else artifacts_dir() / "targets" / target
    parent = parents_root / parent_id
    isa_path = parent / LOWERING / "isa.py"
    if not isa_path.is_file():
        raise SystemExit(f"{parent} has no {LOWERING}/isa.py")

    geometry = geometry_from_address_space(derive_address_space(target))
    baked = package_constants(isa_path.read_text())
    disagree = {
        name: (baked[name], getattr(geometry, field))
        for name, field in CONSTANTS.items()
        if name in baked and baked[name] != getattr(geometry, field)
    }
    if disagree or "DIM" not in baked:
        raise SystemExit(f"{parent_id} baked a different geometry than {target}'s facts derive: {disagree}")

    pass_module = Path(block_schedule.__file__)
    pass_bytes = pass_module.read_bytes()
    rendered = (
        TEMPLATE.read_text()
        .replace('"@GEOMETRY@"', repr(dataclasses.replace(geometry, sources={})))
        .replace('"@KNOBS@"', repr(knobs))
        .replace('"@CONV_KNOBS@"', repr(conv_knobs))
        .replace('"@COALESCE_GATHER@"', repr(bool(coalesce_gather)))
    )
    if "@GEOMETRY@" in rendered or "@KNOBS@" in rendered or "@COALESCE_GATHER@" in rendered:
        raise SystemExit(f"{TEMPLATE} placeholders were not all rendered")

    dest_root.mkdir(parents=True, exist_ok=True)
    staging = dest_root / f".minting_{parent_id}_{label}_{time.time_ns()}"
    shutil.copytree(parent, staging, ignore=shutil.ignore_patterns(*SKIP, "SHA256SUMS"))
    _set_mode(staging, frozen=False)
    (staging / LOWERING / "block_schedule.py").write_bytes(pass_bytes)
    (staging / LOWERING / "scheduled_trace.py").write_text(rendered)
    (staging / LOWERING / "isa.py").write_text(_patch_isa(isa_path.read_text()))

    digest = source_digest(staging)
    package_id = f"{target}_xdsl_sched_{label}_{digest[:12]}"
    manifest_path = staging / "manifest.yaml"
    manifest = yaml.safe_load(manifest_path.read_text()) or {}
    manifest.pop("publication", None)
    manifest.pop("derived_from", None)
    manifest["package_id"] = package_id
    manifest["authoring"] = {
        "author": "merlin scheduled_backend_v0 (mint.py)",
        "generated_by_agent": False,
        "mode": "deterministic_generated_from_spec",
    }
    manifest["lineage"] = {
        "parent_package_id": parent_id,
        "parent_isa_sha256": hashlib.sha256(isa_path.read_bytes()).hexdigest(),
        "minted_by": "merlin/experiments/scheduled_backend_v0/scripts/mint.py",
        "minted_utc": time.strftime("%Y%m%dT%H%M%SZ", time.gmtime()),
        "pass_module": "merlin/python/merlin/compile/scheduling/block_schedule.py",
        "pass_module_sha256": hashlib.sha256(pass_bytes).hexdigest(),
        "knobs": dataclasses.asdict(knobs),
        "conv_knobs": dataclasses.asdict(conv_knobs),
        "coalesce_gather": bool(coalesce_gather),
        "geometry": {f.name: getattr(geometry, f.name) for f in dataclasses.fields(geometry)},
        "source_digest": digest,
        "note": (
            "block moves generated by the vendored scheduling pass; transposed contractions and pooling "
            "use the parent's lowering unchanged. Cycles measured on this package describe this "
            "package only."
        ),
    }
    manifest_path.write_text(yaml.safe_dump(manifest, sort_keys=True))
    _write_sums(staging)

    dest = dest_root / package_id
    if dest.exists():
        verify(dest)
        shutil.rmtree(staging)
        return dest
    staging.rename(dest)
    if freeze:
        _set_mode(dest, frozen=True)
    return dest


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--target", default="gemmini")
    parser.add_argument("--parent", required=True, help="package id of the parent under out/artifacts/targets/")
    parser.add_argument("--label", required=True, help="short readable tag for the knob setting")
    parser.add_argument("--knobs", default="{}", help="JSON Knobs fields for matmul (defaults otherwise)")
    parser.add_argument("--conv-knobs", default=None, help="JSON Knobs fields for conv (default: --knobs)")
    parser.add_argument("--dest", default=None, help="root to mint into (default: out/artifacts/targets/<target>)")
    parser.add_argument(
        "--coalesce-gather",
        action="store_true",
        help="move a gathered block in one multi-row load per run of equally spaced DRAM rows",
    )
    args = parser.parse_args(argv)

    def _knobs(text: str) -> Knobs:
        fields = json.loads(text)
        for key in ("operand_order", "loop_order"):
            if key in fields:
                fields[key] = tuple(fields[key])
        return Knobs(**fields)

    knobs = _knobs(args.knobs)
    conv_knobs = _knobs(args.conv_knobs) if args.conv_knobs is not None else knobs
    print(
        mint(
            args.target,
            args.parent,
            knobs,
            conv_knobs,
            args.label,
            dest_root=Path(args.dest) if args.dest else None,
            coalesce_gather=args.coalesce_gather,
        )
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
